CREATE OR ALTER PROCEDURE dbo.usp_Recharge @SubscriberID int,@Amount decimal(10,2),@PlanID int,@NewBalance decimal(10,2) OUTPUT AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; SET @NewBalance=NULL; IF @Amount<=0 THROW 50201,'Recharge must be positive.',1; BEGIN TRY BEGIN TRAN; DECLARE @T varchar(10); SELECT @T=SubscriberType FROM dbo.Subscribers WITH(UPDLOCK,HOLDLOCK) WHERE SubscriberID=@SubscriberID; IF @T IS NULL THROW 50202,'Subscriber missing.',1; IF @T<>'Prepaid' THROW 50203,'Prepaid only.',1; IF NOT EXISTS(SELECT 1 FROM dbo.Subscribers WHERE SubscriberID=@SubscriberID AND PlanID=@PlanID) THROW 50204,'Invalid plan for subscriber.',1; UPDATE dbo.Subscribers SET Balance=Balance+@Amount WHERE SubscriberID=@SubscriberID; SELECT @NewBalance=Balance FROM dbo.Subscribers WHERE SubscriberID=@SubscriberID; INSERT dbo.RechargeHistory(SubscriberID,Amount,PlanID) VALUES(@SubscriberID,@Amount,@PlanID); COMMIT; END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SET @NewBalance=NULL; THROW; END CATCH END;
GO
CREATE OR ALTER FUNCTION dbo.fn_ValidityDaysLeft(@ID int) RETURNS int AS BEGIN DECLARE @D int; SELECT @D=DATEDIFF(day,CAST(GETDATE() AS date),ValidityEnd) FROM dbo.Subscribers WHERE SubscriberID=@ID; RETURN COALESCE(@D,0); END;
GO
CREATE OR ALTER FUNCTION dbo.fn_LastFiveRecharges(@ID int) RETURNS TABLE AS RETURN SELECT TOP(5) RechargeID,SubscriberID,Amount,RechargeDate,PlanID FROM dbo.RechargeHistory WHERE SubscriberID=@ID ORDER BY RechargeDate DESC,RechargeID DESC;
GO
DECLARE @B decimal(10,2); EXEC dbo.usp_Recharge 301,100,1,@B OUTPUT; SELECT @B NewBalance,dbo.fn_ValidityDaysLeft(301) DaysLeft; SELECT * FROM dbo.fn_LastFiveRecharges(301);